import React from "react"
import PropTypes from "prop-types"
import { Swiper, SwiperSlide } from "swiper/react"
import SwiperCore, { EffectCoverflow, Navigation, Pagination } from "swiper"
import { Link } from "gatsby"
import "swiper/swiper-bundle.min.css"
SwiperCore.use([EffectCoverflow, Navigation, Pagination])
const CoverflowEffect = () => {
  const [width, setWidth] = React.useState(0)
  React.useEffect(() => {
    setWidth(window.innerWidth)
  }, [])
  const SlideBody = props => {
    if (props.to)
      return props.newPage ? (
        <a href={props.to} target="_blank" rel="noreferrer">
          <div>
            <img
              className="bg-contain"
              style={{
                borderRadius: "1rem",
              }}
              src={props.imgSrc}
              alt="img"
            />
          </div>
        </a>
      ) : (
        <Link to={props.to}>
          <div>
            <img
              className="bg-contain"
              style={{
                borderRadius: "1rem",
              }}
              src={props.imgSrc}
              alt="img"
            />
          </div>
        </Link>
      )
    else
      return (
        <div>
          <img
            className="bg-contain"
            style={{
              borderRadius: "1rem",
            }}
            src={props.imgSrc}
            alt="img"
          />
        </div>
      )
  }
  SlideBody.propTypes = {
    to: PropTypes.string,
    imgSrc: PropTypes.string.isRequired,
    newPage: PropTypes.bool,
  }

  let slideritems = [
    {
      to: "https://www.ieee-ras.org/",
      imgSrc:
        "https://ik.imagekit.io/IEEEGECT24/IEEE/photos/join_ras?updatedAt=1721124854913",
      newPage: true,
    },
    {
      to: "http://yess.ieee-link.org",
      imgSrc:
        "https://ik.imagekit.io/IEEEGECT24/IEEE/photos/IEEE%20_YESS.jpg?updatedAt=1721125092536",
      newPage: true,
    },
    {
      to: " https://akiassc24.ieeemesce.org/",
      imgSrc:
        " https://ik.imagekit.io/IEEEGECT24/IEEE/photos/AKISC.jpg?updatedAt=1721125412555",
      newPage: true,
    },
  
  ]

  return (
    <div className="pt-10 pb-5 px-2 sm:px-10">
      <div className="rounded-lg shadow-2xl glass-effect">
        <section className="text-gray-600 body-font">
          <div className="container px-5 py-12 mx-auto sm:py-16">
            <h1 className="font-medium text-3xl mb-8 text-gray-900 text-left ml-8 ">
              Gallery{" "}
            </h1>

            <div className="flex justify-center align-center ">
              <div className="min-w-full md:w-4/6">
                <Swiper
                  spaceBetween={50}
                  slidesPerView={width > 640 ? 3 : 1}
                  pagination={{
                    clickable: true,
                  }}
                  className="mySwiper"
                >
                  {slideritems.map((item, index) => (
                    <SwiperSlide key={index}>
                      <SlideBody
                        to={item.to}
                        imgSrc={item.imgSrc}
                        newPage={item.newPage}
                      />
                    </SwiperSlide>
                  ))}
                </Swiper>
                <p className="text-xs pt-1 sm:text-sm">
                  Click on Event Poster to Register
                </p>
              </div>
            </div>
          </div>
        </section>
      </div>
    </div>
  )
}
export default CoverflowEffect
